import json,pathlib
p=pathlib.Path(__file__).resolve().parent
starter=json.loads((p/'seed-data.json').read_text()); mods=json.loads((p/'modules.json').read_text()); guide=(p/'reference-SAFe-end-to-end-guide.md').read_text(); field_guide=json.loads((p/'field-guidance.json').read_text())
fields={k:list(v[0]) for k,v in starter['modules'].items() if v}
js='window.STARTER='+json.dumps(starter,ensure_ascii=False).replace('</','<\\/')+';\nwindow.MODULES='+json.dumps(mods,ensure_ascii=False).replace('</','<\\/')+';\nwindow.FIELDS='+json.dumps(fields,ensure_ascii=False)+';\nwindow.REFERENCE='+json.dumps(guide,ensure_ascii=False).replace('</','<\\/')+';'

js+='\nwindow.FIELD_GUIDE='+json.dumps(field_guide,ensure_ascii=False).replace('</','<\\/')+';'
css=(p/'styles.css').read_text(); code=(p/'audit.js').read_text()+'\n'+(p/'app.js').read_text()+'\n'+(p/'chat-assistant.js').read_text()
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="SAFe Agile Project And Program Management End to End Tool — interactive insurance IT delivery, governance, budget, release and transformation learning workspace"><title>SAFe Agile Project And Program Management End to End Tool</title><style>'''+css+'''</style></head><body><div class="shell"><aside class="sidebar" id="sidebar" aria-label="Module navigation"></aside><div class="sidebar-backdrop" id="sidebarBackdrop" hidden></div><div class="content"><header class="topbar"><div class="topbar-primary"><button class="btn hamburger" id="hamburger" aria-label="Open navigation" aria-controls="sidebar" aria-expanded="false">☰</button><div class="topbar-brand"><div class="crumb" id="crumb"></div><strong class="topbar-title">SAFe Agile Project And Program Management End to End Tool</strong><span class="topbar-tagline">tool that helps people learn, practice, and confidently manage real IT projects and programs.</span></div></div><button class="btn mobile-tools-toggle" id="toolsToggle" aria-expanded="false" aria-controls="topActions">Tools ▾</button><div class="topright" id="topActions"><span class="pill">Local practice workspace</span><select id="mode" class="select" aria-label="View mode"><option value="project">Project view</option><option value="program">Program view</option></select><button class="btn" data-action="settings">⚙ Settings</button><button class="btn" data-action="import">Import</button><button class="btn" data-action="export">Export workspace</button><button class="btn" data-action="reset">Reset sample</button></div></header><main class="page"><div class="page-head" id="pagehead"></div><div id="main"></div></main></div></div><div id="modal"></div><input type="file" id="importFile" accept="application/json,.json" hidden><script>'''+js+'\n'+code+'''</script></body></html>'''
(p/'index.html').write_text(html)
print('index bytes:',(p/'index.html').stat().st_size)
